import{_ as i,l,o as e,c as d,v as t,p as s,x as r,d as n,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"边缘胶珠去除 EBR","description":"","frontmatter":{"title":"边缘胶珠去除 EBR","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ebr-edge-bead.md","filePath":"litho/ebr-edge-bead.md","lastUpdated":1789023840000}'),p={name:"litho/ebr-edge-bead.md"};function B(c,a,_,m,u,b){const o=l("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="边缘胶珠去除-ebr" tabindex="-1">边缘胶珠去除 EBR <a class="header-anchor" href="#边缘胶珠去除-ebr" aria-label="Permalink to &quot;边缘胶珠去除 EBR&quot;">​</a></h1><div class="epigraph"><p>珠子不参与器件图形，却决定边缘场能不能夹、背面会不会脏。EBR 是机械–溶剂边界，不是又一次曝光。</p><footer>—— 对照轨道工艺中的 edge bead removal 公开描述</footer></div><p><a href="/litho/spin-coating-uniformity">上一课</a>给出径向剖面，边缘必然堆珠。缺口是：珠不切掉，夹盘、传送和边缘曝光都在碰一团厚胶。本课钉 EBR，不把斜边清洗和背面清洗提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>旋涂的自由边使胶在晶圆外沿增厚，成珠或成裙。珠的厚度可以是中心的数倍，软烤后开裂、掉渣，落到曝光场里就是缺陷。夹盘接触珠会污染后续片。把边缘缺陷全写成光刻胶颗粒，会漏掉这圈可预测的几何。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>溶剂喷嘴沿边缘走一圈，溶掉设定宽度的珠（EBR 宽度是配方参数，与曝光场、边缘exclusion 对齐）。有的流程加背面溶剂（backside rinse）防滴到夹盘——细节在后课。EBR 过宽吃掉可曝光面积；过窄留渣。溶剂与胶体系必须匹配，否则中心场被雾。</p><p><span class="marginnote">EBR 之后边缘是「无胶或薄胶」台阶。对准与边缘场剂量补偿要知道这条台阶在哪，否则套刻标记若靠近边缘会踩在厚度跳变上。</span></p>',8)),(e(),s(h,null,{default:r(()=>[E(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEAD%5B%22%E8%BE%B9%E7%BC%98%E7%8F%A0%22%5D%20--%3E%20NOZ%5B%22%E6%BA%B6%E5%89%82%E5%96%B7%E5%98%B4%22%5D%0A%20%20NOZ%20--%3E%20RING%5B%22%E8%AE%BE%E5%AE%9A%E5%AE%BD%E5%BA%A6%E6%97%A0%E7%8F%A0%E7%8E%AF%22%5D%0A%20%20RING%20--%3E%20WEE%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%BE%B9%E7%BC%98%E6%9B%9D%E5%85%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>局部溶解加旋转把溶掉的胶甩出杯。时间与流量决定侧壁是齐的还是锯齿。锯齿在显影后变成边缘残胶源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理斜边金属残留或 CVD 包边。下一课三层堆叠假定中心场厚度已定、边缘已切。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EBR 切的是旋涂自由边的珠，保护夹盘与边缘场。</li><li>宽度是面积与缺陷的权衡，须与 exclusion 对齐。</li><li>出处：轨道 EBR 工艺通识；接续旋涂课。</li></ul>',6))])}const R=i(p,[["render",B]]);export{f as __pageData,R as default};
